<!doctype html>
<meta charset="utf-8">
<title>PROTOTYPE – reservation state machine (throwaway)</title>
<style>
  body { font: 14px system-ui; max-width: 760px; margin: 2em auto; }
  button { margin: 2px; padding: 6px 10px; }
  pre { background: #f4f4f4; padding: 10px; }
  .bad { color: #b00; font-weight: bold; }
  .ok { color: #070; font-weight: bold; }
</style>
<h2>PROTOTYPE: can a reservation reach <code>paid</code> after <code>cancelled</code>?</h2>
<label><input type="checkbox" id="guard"> Webhook handler checks reservation status before marking paid</label>

<h3>Free play</h3>
<div id="events"></div>
<button onclick="reset()">Reset</button>

<h3>Walkthroughs</h3>
<div id="walks"></div>

<h3>Exhaustive search</h3>
<button onclick="search()">Find any path: cancelled, then paid</button>
<div id="result"></div>

<h3>State</h3>
<pre id="state"></pre>
<h3>History</h3>
<pre id="log"></pre>

<script>
// EDIT step() TO MATCH THE REAL RULES. Returns the next state, or null if the event is rejected.
const EVENTS = ['hold', 'startPayment', 'cancel', 'expire', 'paymentSucceeded', 'paymentFailed'];
const INITIAL = { status: 'new', payment: 'none', wasCancelled: false };

function step(s, ev, guarded) {
  const n = { ...s };
  switch (ev) {
    case 'hold':         if (s.status !== 'new') return null; n.status = 'held'; break;
    case 'startPayment': if (s.status !== 'held' || s.payment !== 'none') return null; n.payment = 'pending'; break;
    case 'cancel':       if (s.status !== 'held') return null; n.status = 'cancelled'; break; // payment stays in flight
    case 'expire':       if (s.status !== 'held') return null; n.status = 'expired'; break;
    case 'paymentFailed':if (s.payment !== 'pending') return null; n.payment = 'none'; break;
    case 'paymentSucceeded':
      if (s.payment !== 'pending') return null;          // duplicate webhook is ignored
      if (guarded && s.status !== 'held') n.payment = 'refund_due';
      else { n.payment = 'captured'; n.status = 'paid'; } // naive: overwrites any status
      break;
  }
  if (n.status === 'cancelled') n.wasCancelled = true;
  return n;
}

const WALKS = {
  'Happy path': ['hold', 'startPayment', 'paymentSucceeded'],
  'Late webhook after cancel': ['hold', 'startPayment', 'cancel', 'paymentSucceeded'],
  'Duplicate webhook': ['hold', 'startPayment', 'paymentSucceeded', 'paymentSucceeded'],
  'Cancel before payment': ['hold', 'cancel', 'startPayment'],
};

let state, log;
const $ = id => document.getElementById(id);
const guarded = () => $('guard').checked;

function reset() { state = { ...INITIAL }; log = []; render(); }

function fire(ev) {
  const next = step(state, ev, guarded());
  if (next) state = next;
  log.push(`${ev.padEnd(17)} ${next ? '→ ' + state.status + ' / ' + state.payment : 'REJECTED'}`);
  render();
}

function render() {
  const violated = state.wasCancelled && state.status === 'paid';
  $('state').innerHTML = JSON.stringify(state, null, 2) +
    (violated ? '\n<span class="bad">PAID AFTER CANCELLED</span>' : '');
  $('log').textContent = log.join('\n');
}

function search() {
  const key = s => s.status + '|' + s.payment + '|' + s.wasCancelled;
  const seen = new Set([key(INITIAL)]);
  const queue = [{ s: { ...INITIAL }, path: [] }];
  while (queue.length) {
    const { s, path } = queue.shift();
    if (s.wasCancelled && s.status === 'paid') {
      $('result').innerHTML = `<p class="bad">Reachable: ${path.join(' → ')}</p>`;
      return;
    }
    for (const ev of EVENTS) {
      const n = step(s, ev, guarded());
      if (n && !seen.has(key(n))) { seen.add(key(n)); queue.push({ s: n, path: [...path, ev] }); }
    }
  }
  $('result').innerHTML = `<p class="ok">Not reachable (${seen.size} states explored)</p>`;
}

for (const ev of EVENTS) {
  const b = document.createElement('button');
  b.textContent = ev; b.onclick = () => fire(ev);
  $('events').appendChild(b);
}
for (const [name, steps] of Object.entries(WALKS)) {
  const b = document.createElement('button');
  b.textContent = name; b.onclick = () => { reset(); steps.forEach(fire); };
  $('walks').appendChild(b);
}
reset();
</script>
```

