const WALKS = {
  'happy path': ['hold','startPayment','paymentSucceeded'],
  'cancel, then late webhook': ['hold','startPayment','cancel','paymentSucceeded'],
  'expire, then late webhook': ['hold','startPayment','expire','paymentSucceeded'],
  'duplicate webhook': ['hold','startPayment','paymentSucceeded','paymentSucceeded'],
  'pay after cancel, no payment in flight': ['hold','cancel','startPayment'],
};
const init = () => ({ status: 'draft', payment: 'none', wasCancelled: false });
const mode = () => document.querySelector('[name=mode]:checked').value;

// THE TABLE UNDER TEST: replace with the real rules. Returns the new state, or null if rejected.
function step(s, ev, m) {
  const n = { ...s };
  switch (ev) {
    case 'hold':         if (s.status !== 'draft') return null; n.status = 'held'; break;
    case 'startPayment': if (s.status !== 'held' || s.payment !== 'none') return null; n.payment = 'pending'; break;
    case 'cancel':       if (s.status !== 'held') return null; n.status = 'cancelled'; n.wasCancelled = true; break;
    case 'expire':       if (s.status !== 'held') return null; n.status = 'expired'; break;
    case 'paymentSucceeded':
      if (s.payment !== 'pending') return null;
      if (m === 'naive' || s.status === 'held') { n.status = 'paid'; n.payment = 'captured'; }
      else n.payment = 'refunding';
      break;
    case 'paymentFailed': if (s.payment !== 'pending') return null; n.payment = 'none'; break;
    case 'refund':        if (s.status !== 'paid') return null; n.status = 'refunded'; n.payment = 'refunded'; break;
  }
  return n;
