let state, history, script, pos;
function reset() { state = init(); history = []; script = null; next.hidden = true; render(); }
function fire(ev) {
  const n = step(state, ev, mode());
  history.push(`${ev} -> ${n ? n.status + ' / payment ' + n.payment : 'REJECTED'}`);
  if (n) state = n;
