function nextStep() { fire(script[pos++]); if (pos >= script.length) next.hidden = true; }

// Breadth-first search over every event sequence; returns the shortest path to paid-after-cancelled.
function reach(m) {
  const key = s => s.status + '|' + s.payment + '|' + s.wasCancelled;
  const seen = new Set([key(init())]), queue = [[init(), []]];
  while (queue.length) {
    const [s, path] = queue.shift();
    if (s.status === 'paid' && s.wasCancelled) return path;
    for (const ev of EVENTS) {
      const n = step(s, ev, m);
