  }).join('\n');
}
events.innerHTML = EVENTS.map(e => `<button onclick="fire('${e}')">${e}</button>`).join('');
walks.innerHTML = Object.keys(WALKS).map(w => `<button onclick="startWalk('${w}')">${w}</button>`).join('');
document.querySelectorAll('[name=mode]').forEach(r => r.onchange = reset);
reset();
</script>
